create extension if not exists pgcrypto;

create or replace function public.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$$;

create table if not exists public.users (
  id bigint generated by default as identity primary key,
  name varchar(255) not null,
  email varchar(255) not null,
  email_verified_at timestamptz null,
  password varchar(255) not null,
  remember_token varchar(100) null,
  is_admin boolean not null default false,
  created_at timestamptz null,
  updated_at timestamptz null
);
create unique index if not exists users_email_lower_unique on public.users (lower(email));

create table if not exists public.password_reset_tokens (
  email varchar(255) primary key,
  token varchar(255) not null,
  created_at timestamptz null
);

create table if not exists public.personal_access_tokens (
  id bigint generated by default as identity primary key,
  tokenable_type varchar(255) not null,
  tokenable_id bigint not null,
  name text not null,
  token varchar(64) not null unique,
  abilities text null,
  last_used_at timestamptz null,
  expires_at timestamptz null,
  created_at timestamptz null,
  updated_at timestamptz null
);
create index if not exists personal_access_tokens_tokenable_index on public.personal_access_tokens (tokenable_type, tokenable_id);
create index if not exists personal_access_tokens_expires_at_index on public.personal_access_tokens (expires_at);

create table if not exists public.site_settings (
  id bigint generated by default as identity primary key,
  key varchar(255) not null unique,
  value jsonb null,
  type varchar(30) not null default 'json',
  created_at timestamptz null,
  updated_at timestamptz null
);

create table if not exists public.content_blocks (
  id bigint generated by default as identity primary key,
  key varchar(255) not null,
  locale varchar(5) not null default 'ar',
  title varchar(255) null,
  body text null,
  data jsonb null,
  is_published boolean not null default true,
  created_at timestamptz null,
  updated_at timestamptz null,
  constraint content_blocks_key_locale_unique unique (key, locale)
);
create index if not exists content_blocks_locale_published_index on public.content_blocks (locale, is_published);

create table if not exists public.packages (
  id bigint generated by default as identity primary key,
  slug varchar(255) not null unique,
  name_ar varchar(255) not null,
  name_en varchar(255) not null,
  subtitle_ar varchar(255) null,
  subtitle_en varchar(255) null,
  price_sar integer not null check (price_sar >= 0),
  billing_cycle varchar(30) not null default 'monthly',
  features_ar jsonb null,
  features_en jsonb null,
  sort_order integer not null default 0 check (sort_order >= 0),
  is_featured boolean not null default false,
  is_published boolean not null default true,
  created_at timestamptz null,
  updated_at timestamptz null
);
create index if not exists packages_published_sort_index on public.packages (is_published, sort_order);

create table if not exists public.faqs (
  id bigint generated by default as identity primary key,
  question_ar text not null,
  question_en text not null,
  answer_ar text not null,
  answer_en text not null,
  sort_order integer not null default 0 check (sort_order >= 0),
  is_published boolean not null default true,
  created_at timestamptz null,
  updated_at timestamptz null
);
create index if not exists faqs_published_sort_index on public.faqs (is_published, sort_order);

create table if not exists public.portfolio_projects (
  id bigint generated by default as identity primary key,
  slug varchar(255) not null unique,
  name_ar varchar(255) not null,
  name_en varchar(255) not null,
  category_ar varchar(255) null,
  category_en varchar(255) null,
  description_ar text null,
  description_en text null,
  challenge_ar text null,
  challenge_en text null,
  strategy_ar text null,
  strategy_en text null,
  results jsonb null,
  image_url varchar(2048) null,
  thumbnail_url varchar(2048) null,
  alt_text_ar varchar(255) null,
  alt_text_en varchar(255) null,
  sort_order integer not null default 0 check (sort_order >= 0),
  is_published boolean not null default true,
  created_at timestamptz null,
  updated_at timestamptz null,
  deleted_at timestamptz null
);
create index if not exists portfolio_projects_published_sort_index on public.portfolio_projects (is_published, sort_order);

create table if not exists public.leads (
  id bigint generated by default as identity primary key,
  name varchar(255) not null,
  email varchar(255) null,
  phone varchar(255) null,
  page_url varchar(2048) null,
  service varchar(255) null,
  budget_sar integer null check (budget_sar is null or budget_sar >= 0),
  message text null,
  locale varchar(5) not null default 'ar',
  source varchar(100) not null default 'website',
  status varchar(30) not null default 'new' check (status in ('new','contacted','qualified','won','lost','archived')),
  ip_address inet null,
  user_agent text null,
  consent_at timestamptz null,
  created_at timestamptz null,
  updated_at timestamptz null
);
create index if not exists leads_status_created_index on public.leads (status, created_at desc);
create index if not exists leads_email_index on public.leads (email);

create table if not exists public.media_assets (
  id bigint generated by default as identity primary key,
  disk varchar(100) not null default 's3',
  path varchar(2048) not null,
  url varchar(2048) not null,
  filename varchar(255) not null,
  mime_type varchar(255) null,
  size bigint null check (size is null or size >= 0),
  alt_text varchar(255) null,
  created_by bigint null references public.users(id) on delete set null,
  created_at timestamptz null,
  updated_at timestamptz null
);
create index if not exists media_assets_mime_type_index on public.media_assets (mime_type);

create table if not exists public.audit_logs (
  id bigint generated by default as identity primary key,
  user_id bigint null references public.users(id) on delete set null,
  action varchar(100) not null,
  entity varchar(100) not null,
  entity_id bigint null,
  metadata jsonb null,
  ip_address inet null,
  created_at timestamptz null,
  updated_at timestamptz null
);
create index if not exists audit_logs_entity_index on public.audit_logs (entity, entity_id);
create index if not exists audit_logs_created_at_index on public.audit_logs (created_at desc);

create or replace trigger site_settings_set_updated_at before update on public.site_settings for each row execute function public.set_updated_at();
create or replace trigger content_blocks_set_updated_at before update on public.content_blocks for each row execute function public.set_updated_at();
create or replace trigger packages_set_updated_at before update on public.packages for each row execute function public.set_updated_at();
create or replace trigger faqs_set_updated_at before update on public.faqs for each row execute function public.set_updated_at();
create or replace trigger portfolio_projects_set_updated_at before update on public.portfolio_projects for each row execute function public.set_updated_at();
create or replace trigger leads_set_updated_at before update on public.leads for each row execute function public.set_updated_at();
create or replace trigger media_assets_set_updated_at before update on public.media_assets for each row execute function public.set_updated_at();
create or replace trigger audit_logs_set_updated_at before update on public.audit_logs for each row execute function public.set_updated_at();

alter table public.users enable row level security;
alter table public.password_reset_tokens enable row level security;
alter table public.personal_access_tokens enable row level security;
alter table public.site_settings enable row level security;
alter table public.content_blocks enable row level security;
alter table public.packages enable row level security;
alter table public.faqs enable row level security;
alter table public.portfolio_projects enable row level security;
alter table public.leads enable row level security;
alter table public.media_assets enable row level security;
alter table public.audit_logs enable row level security;
